'use strict';
(()=>{
 const $=s=>document.querySelector(s);let state,model,dirty=false,loaded=false;const fields=[];
 const message=s=>$('#content-status').textContent=s;
 async function call(action,body){const r=await fetch('/api/admin/content'+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось сохранить.');return d;}
 const node=(tag,value)=>{const e=document.createElement(tag);if(value)e.textContent=value;return e;};
 function group(title){const e=node('details'),s=node('summary',title);e.append(s);$('#content-fields').append(e);return e;}
 function field(parent,label,path,type='text',options={}){const l=node('label',label),input=node(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;else input.rows=3;let value=model;for(const k of path)value=value[k];if(type==='checkbox')input.checked=value;else input.value=value;input.required=type!=='checkbox'&&!options.optional;input.maxLength=options.max||2000;if(type==='number'){input.min=0;input.max=1000000;input.step=1;}input.oninput=()=>{dirty=true;$('#content-publish').disabled=true;message('Есть несохранённые изменения. Сначала сохраните черновик.');};l.append(input);parent.append(l);fields.push({input,path,type});
 if(options.image){input.readOnly=true;const img=node('img');img.src=value;img.alt=label;img.className='cms-thumb';const upload=node('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.setAttribute('aria-label','Загрузить: '+label);upload.onchange=async()=>{const file=upload.files[0];if(!file)return;if(file.size>8*1024*1024){message('Файл должен быть не больше 8 МБ.');return;}upload.disabled=true;try{const r=await fetch('/api/admin/content-upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const b=await r.json();if(!r.ok)throw Error(b.error);input.value=b.url;img.src=b.url;input.oninput();message('Фото загружено. Сохраните черновик, проверьте предпросмотр и опубликуйте.');}catch(e){message(e.message);}finally{upload.disabled=false;}};parent.append(img,upload);}
 }
 function render(){model=structuredClone(state.draft);fields.length=0;$('#content-fields').replaceChildren();let g=group('Главная страница: тексты');for(const [k,v] of Object.entries(model.texts))field(g,v.label,['texts',k,'value'],'textarea');
 g=group('Фотографии');field(g,'Фото первого экрана',['heroImage'],'text',{image:true});field(g,'Описание фото для поиска и доступности (alt)',['heroAlt']);field(g,'Фото блока «СТАРТ сейчас»',['cameraImage'],'text',{image:true});
 g=group('Контакты и часы работы');field(g,'Телефон',['phone']);field(g,'Имя Telegram без @',['telegram']);field(g,'Открытие · Москва (например 09:00)',['open']);field(g,'Закрытие · Москва (например 22:00)',['close']);g.append(node('p','Часы применяются к форме заявок. Сезон остаётся с 1 апреля по 1 ноября.'));
 g=group('Флот: цены и описания');model.inventory.forEach((item,i)=>{const box=node('fieldset');box.append(node('legend',item.label));g.append(box);field(box,'Название карточки',['inventory',i,'name']);field(box,'Название в форме',['inventory',i,'label']);field(box,'Цена, ₽ / '+item.unit,['inventory',i,'price'],'number');field(box,'Описание',['inventory',i,'description'],'textarea');if(item.image){if(!item.image.startsWith('/'))item.image='/assets/'+item.image;field(box,'Фотография',['inventory',i,'image'],'text',{image:true});}});
 g=group('Тарифы САПа');for(const [k,label] of Object.entries({day:'Безлимит на день, ₽',season:'Абонемент на сезон, ₽',takeaway:'САП с собой за день, ₽',deposit:'Возвратный залог, ₽'}))field(g,label,['plans',k],'number');
 g=group('SEO и ссылки в соцсетях');field(g,'Заголовок в поиске (title)',['seo','title']);field(g,'Описание в поиске (description)',['seo','description'],'textarea');field(g,'Разрешить поисковикам индексировать главную и страницы услуг',['seo','indexable'],'checkbox');field(g,'Заголовок ссылки в соцсетях',['seo','socialTitle']);field(g,'Описание ссылки в соцсетях',['seo','socialDescription'],'textarea');field(g,'Изображение ссылки (Open Graph)',['seo','socialImage'],'text',{image:true});field(g,'Код Яндекс Вебмастера (только значение content)',['seo','yandexVerification'],'text',{optional:true});field(g,'Код Google Search Console (только значение content)',['seo','googleVerification'],'text',{optional:true});g.append(node('p','Рекомендуется: title около 50–65 символов, description около 120–160. Canonical: https://spotsup.ru/. robots.txt и sitemap.xml обновляются при публикации. Админка и предпросмотр закрыты от индексации. Коды подтверждения берутся из ваших кабинетов поисковых систем.'));
 g=group('SEO: страницы услуг');for(const item of model.inventory){const box=node('fieldset');box.append(node('legend',item.label));g.append(box);field(box,'Заголовок в поиске',['seo','services',item.id,'title']);field(box,'Описание в поиске',['seo','services',item.id,'description'],'textarea');const link=node('a','Открыть страницу услуги');link.href='/prokat/'+item.id+'/';link.target='_blank';link.rel='noopener';box.append(link);}
 $('#content-history').replaceChildren();for(const v of state.versions){const b=node('button','Вернуть в черновик версию от '+new Date(v.created).toLocaleString('ru-RU')+' · '+v.actor);b.type='button';b.onclick=()=>{if(dirty){message('Сначала сохраните текущий черновик.');return;}operate('/restore',{version:v.id},'Версия восстановлена в черновик. Проверьте предпросмотр перед публикацией.');};$('#content-history').append(b);}
 dirty=false;$('#content-publish').disabled=false;
 }
 async function operate(action,extra,success){const buttons=[...$('#content-editor').querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{state=await call(action,{revision:state.revision,...extra});render();message(success);}catch(e){message(e.message);}finally{buttons.forEach(b=>b.disabled=false);$('#content-publish').disabled=dirty;}}
 window.cmsLoad=async user=>{if(user.role!=='admin'){ $('#content-editor').hidden=true;return;}$('#content-editor').hidden=false;if(loaded)return;try{state=await call('');render();loaded=true;}catch(e){message(e.message);}};
 $('#content-form').onsubmit=e=>{e.preventDefault();for(const f of fields){let obj=model;for(const k of f.path.slice(0,-1))obj=obj[k];obj[f.path.at(-1)]=f.type==='checkbox'?f.input.checked:f.type==='number'?Number(f.input.value):f.input.value;}operate('/save',{content:model},'Черновик сохранён. Откройте предпросмотр, затем опубликуйте.');};
 $('#content-publish').onclick=()=>{if(dirty){message('Сначала сохраните черновик.');return;}operate('/publish',{},'Изменения опубликованы на сайте.');};
 $('#content-reload').onclick=async()=>{if(dirty){message('Есть несохранённые изменения. Сохраните их или перезагрузите страницу, чтобы отбросить.');return;}loaded=false;await window.cmsLoad({role:'admin'});};
})();
